Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug was caused by a missing closing parenthesis in a conditional statement within the `es_isr` function, which resulted in a syntax error that prevented the code from compiling correctly. This error was introduced by a previous commit that modified the logic of the condition but did not properly close the statement.

Here is the patch:

 static void es_isr(struct scc_priv *priv)
 {
 	int i, rr0, drr0, res;
 	unsigned long flags;

 	/* Read status, reset interrupt bit (open latches) */
 	rr0 = read_scc(priv, R0);
 	write_scc(priv, R0, RES_EXT_INT);
 	drr0 = priv->rr0 ^ rr0;
 	priv->rr0 = rr0;

 	/* Transmit underrun (2.4.9.6). We can't check the TxEOM flag, since
 	   it might have already been cleared again by AUTOEOM. */
 	if (priv->state == TX_DATA) {
 		/* Get remaining bytes */
 		i = priv->tx_tail;
 		if (priv->param.dma >= 0) {
 			disable_dma(priv->param.dma);
 			flags = claim_dma_lock();
 			res = get_dma_residue(priv->param.dma);
 			release_dma_lock(flags);
 		} else {
 			res = priv->tx_len[i] - priv->tx_ptr;
 			priv->tx_ptr = 0;
 		}
 		/* Disable DREQ / TX interrupt */
 		if (priv->param.dma >= 0 && priv->type == TYPE_TWIN)
 			outb(0, priv->card_base + TWIN_DMA_CFG);
 		else
 			write_scc(priv, R1, EXT_INT_ENAB | WT_FN_RDYFN);
 		if (res) {
 			/* Update packet statistics */
 			priv->dev->stats.tx_errors++;
 			priv->dev->stats.tx_fifo_errors++;
 			/* Other underrun interrupts may already be waiting */
 			write_scc(priv, R0, RES_EXT_INT);
 			write_scc(priv, R0, RES_EXT_INT);
 		} else {
 			/* Update packet statistics */
 			priv->dev->stats.tx_packets++;
 			priv->dev->stats.tx_bytes += priv->tx_len[i];
 			/* Remove frame from FIFO */
 			priv->tx_tail = (i + 1) % NUM_TX_BUF;
 			priv->tx_count--;
 			/* Inform upper layers */
 			netif_wake_queue(priv->dev);
 		}
 		/* Switch state */
 		write_scc(priv, R15, 0);
 		if (priv->tx_count &&
-		    time_is_after_jiffies(priv->tx_start + priv->param.txtimeout) {
+		    time_is_after_jiffies(priv->tx_start + priv->param.txtimeout)) {
 			priv->state = TX_PAUSE;
 			start_timer(priv, priv->param.txpause, 0);
 		} else {
 			priv->state = TX_TAIL;
 			start_timer(priv, priv->param.txtail, 0);
 		}
 	}

 	/* DCD transition */
 	if (drr0 & DCD) {
 		if (rr0 & DCD) {
 			switch (priv->state) {
 			case IDLE:
 			case WAIT:
 				priv->state = DCD_ON;
 				write_scc(priv, R15, 0);
 				start_timer(priv, priv->param.dcdon, 0);
 			}
 		} else {
 			switch (priv->state) {
 			case RX_ON:
 				rx_off(priv);
 				priv->state = DCD_OFF;
 				write_scc(priv, R15, 0);
 				start_timer(priv, priv->param.dcdoff, 0);
 			}
 		}
 	}

 	/* CTS transition */
 	if ((drr0 & CTS) && (~rr0 & CTS) && priv->type != TYPE_TWIN)
 		tm_isr(priv);

 }



